from queueing import payload

def submit(owner, enqueue=None, batch_size=20):
    # Validate batch_size before enqueue
    # Reject bool values (True/False are technically integers in Python)
    if isinstance(batch_size, bool):
        raise ValueError("batch_size must be an integer, not a boolean")

    if not isinstance(batch_size, int) or batch_size < 1 or batch_size > 100:
        raise ValueError("batch_size must be an integer between 1 and 100")

    # If enqueue is None (legacy call with no enqueue), just return payload
    if enqueue is None:
        return payload(owner, batch_size=20)

    # Create payload with batch_size
    result = enqueue(payload(owner, batch_size=batch_size))
    return result

def execute(task, process):
    # Use batch_size from payload if present, otherwise default to 20
    batch_size = task.get("batch_size", 20)
    return process(task["owner"], batch_size)

